<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Accessor\DcrInitialAccessTokenMaxUsesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenMaxUsesAccessor trait.
 *
 * Covers null default, string/VO assignment via withMaxUses,
 * getMaxUses/maxUses accessors, and isMaxUsesChanged with/without original.
 */
class DcrInitialAccessTokenMaxUsesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withMaxUses creates a new instance with the MaxUses set
     * from a string value, and getMaxUses returns the primitive string.
     */
    public function testWithMaxUsesFromString(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenMaxUsesAccessorUnitTest();

        // Act
        $result = $holder->withMaxUses(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->getMaxUses());
    }
    /**
     * Asserts that withmaxUses has access to the value object
     * from a string value, and getMaxUses returns the primitive string.
     */
    public function testWithMaxUsesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenMaxUsesAccessorUnitTest();

        // Act
        $result = $holder->withMaxUses(1);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(1, $result->maxUses()->value());
    }
    public function testChangedMaxUses(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenMaxUsesAccessorUnitTest()->withMaxUses(1);
        $original = $holder->withMaxUses(1);
        $same = $holder->withMaxUses(1);
        $modified = $holder->withMaxUses(2);

        // Act
        $withSame = $original->isMaxUsesChanged($same);
        $withDiferent = $original->isMaxUsesChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithDcrInitialAccessTokenMaxUsesAccessorUnitTest
{
    use DcrInitialAccessTokenMaxUsesAccessor;
}
